function avatarEl(name,size){
  size=size||28;
  const p=name.trim().split(' ');
  const ini=(p[0][0]+(p[1]?p[1][0]:'')).toUpperCase();
  const col=AVCOLS[name.charCodeAt(0)%AVCOLS.length];
  const el=document.createElement('div');
  el.className='avatar';
  el.style.cssText='width:'+size+'px;height:'+size+'px;border-radius:50%;background:'+col+';display:flex;align-items:center;justify-content:center;font-family:Barlow Condensed,sans-serif;font-size:'+(size<=28?11:13)+'px;font-weight:700;color:#fff;flex-shrink:0';
  el.textContent=ini;return el;
}
// Avatar colors based on name initial
function silhouetteEl(size){
  size=size||28;
  var el=document.createElement('div');
  el.style.cssText='width:'+size+'px;height:'+size+'px;border-radius:50%;background:var(--dark3);border:1px solid var(--dark4);display:flex;align-items:center;justify-content:center;flex-shrink:0;overflow:hidden';
  el.innerHTML='<svg width="'+(size*.7)+'" height="'+(size*.7)+'" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="8" r="4" fill="rgba(255,255,255,0.35)"/><path d="M4 20c0-4 3.6-7 8-7s8 3 8 7" fill="rgba(255,255,255,0.35)"/></svg>';
  return el;
}
function photoEl(name,url,size){
  size=size||28;
  if(url){
    var img=document.createElement('img');
    img.className='pimg';img.src=url;img.alt=name;
    img.style.cssText='width:'+size+'px;height:'+size+'px;border-radius:50%;object-fit:cover;flex-shrink:0;background:var(--dark3);transition:transform .15s,box-shadow .15s;';
    img.addEventListener('mouseenter',function(){this.style.transform='scale(1.12)';this.style.boxShadow='0 2px 8px rgba(0,0,0,.5)';});
    img.addEventListener('mouseleave',function(){this.style.transform='';this.style.boxShadow='';});
    img.onerror=function(){this.replaceWith(silhouetteEl(size));};return img;
  }
  return silhouetteEl(size);
}
// DONUT RATING — estilo FIFA/SofaScore
function nivelColor(v){
  if(v>=85)return'#60a5fa';
  if(v>=75)return'#22c55e';
  if(v>=65)return'#f59e0b';
  if(v>=55)return'#f97316';
  return'#ef4444';
}
function drawDonut(canvas,value,color,size){
  const ctx=canvas.getContext('2d');const s=size||32;
  const dpr=window.devicePixelRatio||1;
  canvas.width=s*dpr;canvas.height=s*dpr;
  canvas.style.width=s+'px';canvas.style.height=s+'px';
  ctx.scale(dpr,dpr);
  const cx=s/2,cy=s/2,r=s/2-2,lw=size>=44?4:3;
  ctx.clearRect(0,0,s,s);
  // track
  ctx.beginPath();ctx.arc(cx,cy,r,0,2*Math.PI);
  ctx.strokeStyle='rgba(255,255,255,.08)';ctx.lineWidth=lw;ctx.stroke();
  // fill
  const pct=(value||0)/100;
  ctx.beginPath();ctx.arc(cx,cy,r,-Math.PI/2,-Math.PI/2+pct*2*Math.PI);
  ctx.strokeStyle=color;ctx.lineWidth=lw;ctx.lineCap='round';ctx.stroke();
}
function nivelDonutEl(nivel,size){
  size=size||32;
  const n=Math.max(0,parseFloat(nivel)||0);
  const col=nivelColor(n);
  const wrap=document.createElement('div');wrap.className='donut-wrap';
  wrap.style.width=size+'px';wrap.style.height=size+'px';
  const canvas=document.createElement('canvas');
  drawDonut(canvas,n,col,size);
  const label=document.createElement('div');label.className='donut-num';
  label.style.cssText='font-size:'+(size>=44?13:9)+'px;color:'+col;
  label.textContent=n||'—';
  wrap.appendChild(canvas);wrap.appendChild(label);
  return wrap;
}
// keep old name as alias for table usage
function nivelBarEl(nivel){return nivelDonutEl(nivel,32);}

// STATUS TAG helper
function statusTagEl(status){
  const map={
    'Titular':'stag-titular','Importante':'stag-importante',
    'Compõe elenco':'stag-compoe','Vender':'stag-vender','Dispensável':'stag-dispensavel'
  };
  const span=document.createElement('span');
  span.className='stag '+(map[status]||'stag-compoe');
  span.textContent=status;
  return span;
}
function starsEl(prio,small){
  const wrap=document.createElement('div');wrap.className='stars';
  const count=prio===4?4:3;const col=starColor(prio);
  for(let i=1;i<=count;i++){
    const s=document.createElement('span');s.style.cssText='font-size:'+(small?'11':'13')+'px;color:'+(i<=prio?col:'var(--dark4)');s.textContent='★';wrap.appendChild(s);
  }
  if(prio>0){const l=document.createElement('span');l.style.cssText='font-size:9px;color:var(--gray);margin-left:2px';l.textContent=prioLabel(prio);wrap.appendChild(l);}
  return wrap;
}

// MULTI-SELECT FILTER
function buildMF(wrapId,btnId,ddId,opts,sel,onChange,allLabel){
  const dd=document.getElementById(ddId);
  const btn=document.getElementById(btnId);
  dd.innerHTML='';
  // All
  const allOpt=document.createElement('div');allOpt.className='mf-opt mf-all'+(sel.length===0?' sel':'');
  allOpt.innerHTML='<div class="mf-check">'+(sel.length===0?'✓':'')+'</div><span>'+(allLabel||'Todos')+'</span>';
  allOpt.onclick=function(){sel.splice(0,sel.length);onChange();buildMF(wrapId,btnId,ddId,opts,sel,onChange,allLabel);updateMFBtn(btnId,sel,allLabel||'Todos');};
  dd.appendChild(allOpt);
  opts.forEach(function(o){
    const isS=sel.includes(o);
    const opt=document.createElement('div');opt.className='mf-opt'+(isS?' sel':'');
    opt.innerHTML='<div class="mf-check">'+(isS?'✓':'')+'</div><span>'+o+'</span>';
    opt.onclick=function(e){e.stopPropagation();const idx=sel.indexOf(o);if(idx>=0)sel.splice(idx,1);else sel.push(o);onChange();buildMF(wrapId,btnId,ddId,opts,sel,onChange,allLabel);updateMFBtn(btnId,sel,allLabel||'Todos');};
    dd.appendChild(opt);
  });
  btn.onclick=function(e){e.stopPropagation();const open=dd.classList.contains('open');closeAllDD();if(!open){dd.classList.add('open');btn.classList.add('open');}};
}
function updateMFBtn(btnId,sel,def){
  const btn=document.getElementById(btnId);
  const lbl=btn.querySelector('span');
  lbl.textContent=sel.length===0?'▾':sel.length+' ▾';
  if(sel.length>0)btn.style.borderColor='var(--red)'; else btn.style.borderColor='';
}
function closeAllDD(){document.querySelectorAll('.mf-dropdown').forEach(function(d){d.classList.remove('open');});document.querySelectorAll('.mf-btn').forEach(function(b){b.classList.remove('open');});}
document.addEventListener('click',closeAllDD);

function initFilters(){
  buildMF('mf-pos-wrap','mf-pos-btn','mf-pos-dd',POSITIONS,ST.filterPos,function(){renderTable();},'Todas posições');
  buildMF('mf-status-wrap','mf-status-btn','mf-status-dd',SLIST,ST.filterStatus,function(){renderTable();},'Todos status');
  buildMF('mf-tpos-wrap','mf-tpos-btn','mf-tpos-dd',POSITIONS,ST.filterTPos,function(){renderMercado();},'Todas posições');
  buildMF('mf-tprio-wrap','mf-tprio-btn','mf-tprio-dd',['Baixa','Média','Alta','Oportunidade'],ST.filterTPrio,function(){renderMercado();},'Todas prioridades');
}

// SORT
function initSortBtns(){
  const sorts=[{k:'age',l:'Idade'},{k:'nivel',l:'Nível'},{k:'valor',l:'Valor'},{k:'pos',l:'Posição'}];
  const el=document.getElementById('sort-btns');if(el){el.innerHTML='';
  sorts.forEach(function(s){
    const b=document.createElement('button');b.className='sort-btn'+(ST.sortKey===s.k?' active':'');
    b.textContent=s.l+(ST.sortKey===s.k?(ST.sortAsc?' ↑':' ↓'):'');
    b.onclick=function(){if(ST.sortKey===s.k)ST.sortAsc=!ST.sortAsc;else{ST.sortKey=s.k;ST.sortAsc=true;}initSortBtns();renderTable();};
    el.appendChild(b);
  });}
  const te=document.getElementById('tsort-btns');if(te){te.innerHTML='';
  sorts.forEach(function(s){
    const b=document.createElement('button');b.className='sort-btn'+(ST.tsortKey===s.k?' active':'');
    b.textContent=s.l+(ST.tsortKey===s.k?(ST.tsortAsc?' ↑':' ↓'):'');
    b.onclick=function(){if(ST.tsortKey===s.k)ST.tsortAsc=!ST.tsortAsc;else{ST.tsortKey=s.k;ST.tsortAsc=true;}initSortBtns();renderMercado();};
    te.appendChild(b);
  });}
}

